    <style>
      :root {
        color-scheme: light;
        --bg: #f3f6fb;
        --panel: #ffffff;
        --panel-border: #d9e2f2;
        --text: #14213d;
        --muted: #52607a;
        --accent: #3b82f6;
        --accent-strong: #1d4ed8;
        --accent-soft: #dbeafe;
        --success-bg: #ecfdf3;
        --success-text: #166534;
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, #ffffff 0, #edf4ff 38%, var(--bg) 100%);
        color: var(--text);
      }

