        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 24px;
      }

      .card {
        width: min(100%, 560px);
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        padding: 32px;
        box-shadow: var(--shadow);
      }

      .eyebrow {
        margin: 0 0 10px;
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--accent-strong);
      }

      h1 {
        margin: 0 0 12px;
        font-size: clamp(1.9rem, 3.5vw, 2.4rem);
        line-height: 1.1;
      }

      .intro {
        margin: 0 0 28px;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 24px;
      }

      .form-field {
        padding: 0;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        margin-bottom: 16px;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .options {
        display: grid;
        gap: 12px;
      }

      .option {
        position: relative;
      }

      .option input {
        position: absolute;
        opacity: 0;
        inset: 0;
      }

      .option label {
        display: flex;
        align-items: center;
        gap: 14px;
        width: 100%;
        padding: 16px 18px;
        border: 1px solid var(--panel-border);
        border-radius: 16px;
        background: #fff;
        color: var(--text);
        cursor: pointer;
        transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease,
          box-shadow 0.2s ease;
      }

      .option label::before {
        content: "";
        width: 20px;
        height: 20px;
        border-radius: 50%;
        border: 2px solid #8ca0bf;
        background: #fff;
        flex: 0 0 20px;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
      }

      .option input:checked + label {
        border-color: var(--accent);
        background: var(--accent-soft);
        box-shadow: 0 10px 30px rgba(59, 130, 246, 0.14);
      }

      .option input:checked + label::before {
        border-color: var(--accent-strong);
        background:
          radial-gradient(circle, var(--accent-strong) 0 46%, transparent 47% 100%);
      }

      .option label:hover {
        transform: translateY(-1px);
      }

      .option input:focus-visible + label,
      button:focus-visible {
        outline: 3px solid var(--accent-strong);
        outline-offset: 3px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 14px;
        padding: 14px 20px;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        cursor: pointer;
        transition: transform 0.2s ease, box-shadow 0.2s ease;
        box-shadow: 0 14px 30px rgba(29, 78, 216, 0.26);
      }

      button:hover {
        transform: translateY(-1px);
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        font-weight: 600;
        color: var(--success-text);
      }

      .status[data-visible="true"] {
        padding: 12px 14px;
        border-radius: 14px;
        background: var(--success-bg);
      }

      @media (max-width: 480px) {
        .card {
          padding: 24px;
          border-radius: 20px;
        }
      }

      @media (forced-colors: active) {
        body {
          background: Canvas;
        }

        .card,
        .option label,
        button,
        .status[data-visible="true"] {
          border: 1px solid ButtonText;
          box-shadow: none;
        }

        .card,
        .option label,
        .status[data-visible="true"] {
          background: Canvas;
          color: CanvasText;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }

        .option label::before {
          border-color: ButtonText;
          background: Canvas;
        }

        .option input:checked + label::before {
          background: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Preferences</p>
        <h1 id="page-title">Choose how you want to stay updated</h1>
        <p class="intro">
          Select one notification channel so we can send account alerts and product updates the
          way you prefer.
        </p>

        <form id="notification-form">
          <div class="form-field">
            <fieldset>
              <legend>How do you prefer to receive notifications?</legend>
              <div class="options">
                <div class="option">
                  <input type="radio" id="notification-email" name="notificationPreference" value="Email" required />
                  <label for="notification-email">Email</label>
                </div>
                <div class="option">
                  <input type="radio" id="notification-sms" name="notificationPreference" value="SMS" />
                  <label for="notification-sms">SMS</label>
                </div>
                <div class="option">
                  <input
                    type="radio"
                    id="notification-push"
                    name="notificationPreference"
                    value="Push Notifications"
                  />
                  <label for="notification-push">Push Notifications</label>
                </div>
              </div>
            </fieldset>
          </div>

          <button type="submit">Submit</button>
          <p class="status" id="status-message" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("notification-form");
      const statusMessage = document.getElementById("status-message");

      form.addEventListener("submit", function (event) {
        event.preventDefault();

        const selectedOption = form.querySelector('input[name="notificationPreference"]:checked');
        const message = "Preference saved: " + selectedOption.value + ".";

        statusMessage.textContent = message;
        statusMessage.dataset.visible = "true";
      });
    </script>
  </body>
</html>
